## ✅ Full C Program: Number System Conversions

```c
#include <stdio.h>
#include <math.h>
#include <string.h>

void decimalToBinary(int n) {
    int binary[32], i = 0;
    while (n > 0) {
        binary[i++] = n % 2;
        n /= 2;
    }
    printf("Binary: ");
    for (int j = i - 1; j >= 0; j--)
        printf("%d", binary[j]);
    printf("\n");
}

void binaryToDecimal(char bin[]) {
    int dec = 0, len = strlen(bin);
    for (int i = 0; i < len; i++)
        dec = dec * 2 + (bin[i] - '0');
    printf("Decimal: %d\n", dec);
}

void decimalToOctal(int n) {
    int oct[32], i = 0;
    while (n > 0) {
        oct[i++] = n % 8;
        n /= 8;
    }
    printf("Octal: ");
    for (int j = i - 1; j >= 0; j--)
        printf("%d", oct[j]);
    printf("\n");
}

void octalToDecimal(char oct[]) {
    int dec = 0, len = strlen(oct);
    for (int i = 0; i < len; i++)
        dec = dec * 8 + (oct[i] - '0');
    printf("Decimal: %d\n", dec);
}

void decimalToHexadecimal(int n) {
    char hex[32];
    int i = 0;
    while (n > 0) {
        int r = n % 16;
        if (r < 10)
            hex[i++] = r + '0';
        else
            hex[i++] = r - 10 + 'A';
        n /= 16;
    }
    printf("Hexadecimal: ");
    for (int j = i - 1; j >= 0; j--)
        printf("%c", hex[j]);
    printf("\n");
}

int hexDigitToDecimal(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    else if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    else if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    else return -1;
}

void hexadecimalToDecimal(char hex[]) {
    int dec = 0, len = strlen(hex);
    for (int i = 0; i < len; i++) {
        int val = hexDigitToDecimal(hex[i]);
        if (val == -1) {
            printf("Invalid Hexadecimal Digit\n");
            return;
        }
        dec = dec * 16 + val;
    }
    printf("Decimal: %d\n", dec);
}

int main() {
    int choice, num;
    char str[100];

    do {
        printf("\n===== Number System Conversion Menu =====\n");
        printf("1. Decimal to Binary\n");
        printf("2. Binary to Decimal\n");
        printf("3. Decimal to Octal\n");
        printf("4. Octal to Decimal\n");
        printf("5. Decimal to Hexadecimal\n");
        printf("6. Hexadecimal to Decimal\n");
        printf("0. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter Decimal number: ");
                scanf("%d", &num);
                decimalToBinary(num);
                break;
            case 2:
                printf("Enter Binary number: ");
                scanf("%s", str);
                binaryToDecimal(str);
                break;
            case 3:
                printf("Enter Decimal number: ");
                scanf("%d", &num);
                decimalToOctal(num);
                break;
            case 4:
                printf("Enter Octal number: ");
                scanf("%s", str);
                octalToDecimal(str);
                break;
            case 5:
                printf("Enter Decimal number: ");
                scanf("%d", &num);
                decimalToHexadecimal(num);
                break;
            case 6:
                printf("Enter Hexadecimal number: ");
                scanf("%s", str);
                hexadecimalToDecimal(str);
                break;
            case 0:
                printf("Exiting program.\n");
                break;
            default:
                printf("Invalid choice. Try again.\n");
        }

    } while (choice != 0);

    return 0;
}
```

